# A comment above the module's docstring, which still opens the module.
"""Shapes on a plane, to hold what the chunkers make of a file."""

import functools
import math
from dataclasses import dataclass


def area(radius: float) -> float:
    """The area of a circle."""
    return math.pi * radius**2


class Shape:
    """A shape on a plane."""

    sides = 0

    def perimeter(self) -> float:
        return 0.0

    @property
    def label(self) -> str:
        return type(self).__name__

    class Corner:
        def angle(self) -> float:
            return 90.0


@dataclass(frozen=True)
# A comment between the decorators, which stays with the class.
@functools.total_ordering
class Square(Shape):
    side: float

    async def scaled(self, factor: float) -> "Square":
        def doubled(value: float) -> float:
            return value * 2

        return Square(doubled(self.side) * factor)

